<?php use SwimlogStandalone\SwimSessionAnalysis as SA;use SwimLogEvaluation\Workout;$title=$screen==='pace'?'Pace Consistency':'Repeat-set Analysis'; ?>
<section class="calendar-panel workout-page" aria-labelledby="session-analysis-title"><h2 id="session-analysis-title"><?php echo esc_html($title); ?></h2>
<?php if(is_wp_error($sessionAnalysis)): ?><p role="alert"><?php echo esc_html($sessionAnalysis->get_error_message()); ?></p><?php else:$m=$sessionAnalysis; ?>
<?php if(!$m['choices']): ?><p>No recorded pool swims are available.</p><?php else: ?>
<form method="get" class="log-filters"><input type="hidden" name="screen" value="<?php echo esc_attr($screen); ?>"><input type="hidden" name="analysis_page" value="<?php echo esc_attr($m['page']); ?>"><div><label for="analysis-swim">Pool swim</label><select name="swim_id" id="analysis-swim"><?php foreach($m['choices']as$c): ?><option value="<?php echo esc_attr($c['id']); ?>" <?php selected($m['swim']['id']??0,$c['id']); ?>><?php echo esc_html($c['date'].' · #'.$c['id']); ?></option><?php endforeach; ?></select></div><button>Analyze swim</button></form>
<nav class="plan-actions" aria-label="Swim selection pages"><?php if($m['page']>1): ?><a class="control" href="<?php echo esc_url('/?screen='.$screen.'&analysis_page='.($m['page']-1)); ?>">Newer swims</a><?php endif;if($m['page']<$m['pages']): ?><a class="control" href="<?php echo esc_url('/?screen='.$screen.'&analysis_page='.($m['page']+1)); ?>">Older swims</a><?php endif; ?></nav>
<?php if($m['swim']):$s=$m['swim']; ?><h3><?php echo esc_html($s['date'].' · '.$s['pool'].' '.$s['course'].' pool'); ?></h3><div class="plan-actions"><a class="control" href="<?php echo esc_url('/?workout='.$s['id']); ?>">View workout</a><a class="control" href="<?php echo esc_url('/?screen='.($screen==='pace'?'repeats':'pace').'&swim_id='.$s['id']); ?>"><?php echo $screen==='pace'?'Repeat-set Analysis':'Pace Consistency'; ?></a></div>
<?php if($screen==='pace'): ?><p>Active-length pace and variation, grouped by stroke and native pool course. Rest and zero-distance lengths are excluded. Missing times remain missing. Manual measured repetitions are not split into invented length times; use Repeat-set Analysis for those sessions.</p><p>CV is the plugin’s population coefficient of variation of recorded length pace. Lower CV means more consistent sampled pace, not necessarily better technique or fitness. Charts connect timed samples in recorded order; omitted untimed lengths are not evidence of steady pace between points.</p>
<?php if(!$m['groups']): ?><p>No qualifying active-length evidence is available.</p><?php endif;foreach($m['groups']as$g): ?><section class="comparison-stroke"><h3><?php echo esc_html($g['stroke']); ?></h3><dl class="workout-metrics"><?php foreach(array('Timed / active lengths'=>$g['timed_lengths'].' / '.$g['active_lengths'],'Average pace per 100 '.$s['course']=>Workout::format_duration($g['avg_pace_100_ms']),'Fastest length pace per 100 '.$s['course']=>Workout::format_duration($g['best_pace_100_ms']),'Pace consistency (CV)'=>$g['pace_consistency_cv']===null?'Unavailable: at least two timed lengths required':number_format_i18n($g['pace_consistency_cv'],2).'%')as$label=>$value): ?><div><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html($value); ?></dd></div><?php endforeach; ?></dl><?php $samples=$m['samples'][$g['stroke']]??array();echo SA::chart($samples,$g['stroke'].' active-length pace per 100 '.$s['course']); ?><details><summary>Exact timed-length paces</summary><div class="entry-compare"><table><thead><tr><th scope="col">Length</th><th scope="col">Pace per 100 <?php echo esc_html($s['course']); ?></th></tr></thead><tbody><?php foreach($samples as$p): ?><tr><td><?php echo esc_html($p['sequence']); ?></td><td><?php echo esc_html(Workout::format_duration($p['pace'])); ?></td></tr><?php endforeach; ?></tbody></table></div></details></section><?php endforeach; ?>
<?php else: ?><p>Explicitly measured manual repetitions are grouped by their saved set. Imported candidates are consecutive same-stroke, same-distance laps with the same timing basis, allowing intervening recorded rest laps. Candidates are not proof of a prescribed set. Long continuous laps are never divided into guessed repetitions.</p><p>Elapsed lap time can include rest within the lap. Recorded moving time is used when available; different timing bases are kept apart. Interval/send-off and whole-set times are not treated as measured repetition times. Missing rest is unknown, not zero.</p>
<?php if(!$m['sets']): ?><p>No repeated measured manual sets or candidate repeated lap groups are available.</p><?php endif; ?>
<?php foreach($m['sets']as$set):$g=$set['metrics']; ?><section class="comparison-stroke"><h3><?php echo esc_html($set['label'].' · '.count($set['reps']).' × '.$set['distance'].' '.$s['course'].' '.$set['stroke']); ?></h3><p><?php echo esc_html($set['reps'][0]['basis']); ?></p><dl class="workout-metrics"><?php foreach(array('Timed / recorded repetitions'=>($g['timed_lengths']??0).' / '.count($set['reps']),'Average pace per 100 '.$s['course']=>Workout::format_duration($g['avg_pace_100_ms']??null),'Pace consistency (CV)'=>isset($g['pace_consistency_cv'])?number_format_i18n($g['pace_consistency_cv'],2).'%':'Unavailable: at least two timed repetitions required','Fastest recorded repetition'=>Workout::format_duration($set['fastest']),'Slowest recorded repetition'=>Workout::format_duration($set['slowest']),'First-to-last time change'=>$set['change']===null?'Unavailable':($set['change']>0?'+':($set['change']<0?'−':'')).Workout::format_duration(abs($set['change'])))as$label=>$value): ?><div><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html($value); ?></dd></div><?php endforeach; ?></dl><?php if(array_key_exists('entered_rest',$set)): ?><p>Entered rest for this set: <?php echo esc_html($set['entered_rest']===null?'Unknown':Workout::format_duration($set['entered_rest'])); ?>. This is not individually measured rest after each repetition.</p><?php endif; ?><p>Positive change means the last repetition took longer. This alone does not establish fatigue.</p>
<?php $samples=array();foreach($set['reps']as$i=>$r)if($r['pace']!==null)$samples[]=array('sequence'=>$r['number'],'pace'=>$r['pace']);echo SA::chart($samples,'Recorded repetition pace per 100 '.$s['course']); ?>
<div class="entry-compare"><table><caption><?php echo esc_html($set['rest_label']); ?></caption><thead><tr><th scope="col">Recorded repetition/lap</th><th scope="col">Time</th><th scope="col">Rest after</th></tr></thead><tbody><?php foreach($set['reps']as$r): ?><tr><td><?php echo esc_html($r['number']); ?></td><td><?php echo esc_html(Workout::format_duration($r['ms'])); ?></td><td><?php echo esc_html($r['rest']===null?'Unknown':Workout::format_duration($r['rest'])); ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endforeach; ?><p><?php echo esc_html($m['omitted']); ?> non-repeated or unsupported sets/lap runs omitted. All normalized history remains available in workout details.</p>
<?php endif;endif;endif;endif; ?></section>
